[{"order":1,"type":"heading","text":"Low-level Calls: call, delegatecall, and staticcall in Solidity"},{"order":2,"type":"paragraph","text":"Solidity provides three low-level functions to interact with other contracts and addresses: call, delegatecall, and staticcall. These functions bypass standard type checking, function existence checks, and revert propagation, making them powerful yet potentially hazardous tools for advanced smart contract development."},{"order":3,"type":"subheading","text":"1. The call Function"},{"order":4,"type":"paragraph","text":"The call function is the standard low-level method used to send Ether to other addresses and invoke functions on other contracts. It executes in the context of the target contract, meaning state variables of the target contract are modified."},{"order":5,"type":"code","text":"contract Receiver {
    event Received(address caller, uint256 amount, string message);

    function foo(string memory _message) public payable returns (uint256) {
        emit Received(msg.sender, msg.value, _message);
        return 42;
    }
}

contract Caller {
    event Response(bool success, bytes data);

    function callFoo(address payable _addr, string memory _message) public payable {
        (bool success, bytes memory data) = _addr.call{value: msg.value}(abi.encodeWithSignature("foo(string)", _message));
        emit Response(success, data);
    }
}"},{"order":6,"type":"bullet_point","text":"Returns a tuple of (bool success, bytes memory data)."},{"order":7,"type":"bullet_point","text":"Allows forwarding specific amounts of Ether using the {value: ...} option."},{"order":8,"type":"bullet_point","text":"Allows specifying gas limits using the {gas: ...} option."},{"order":9,"type":"subheading","text":"2. The delegatecall Function"},{"order":10,"type":"paragraph","text":"delegatecall is identical to call, with one crucial difference: code at the target address is executed in the context of the calling contract. This means msg.sender and msg.value do not change, and any state modifications affect the calling contract's storage, not the target contract's."},{"order":11,"type":"code","text":"contract Logic {
    uint256 public num;
    address public sender;

    function setVars(uint256 _num) public payable {
        num = _num;
        sender = msg.sender;
    }
}

contract Proxy {
    uint256 public num;
    address public sender;

    function setVars(address _logic, uint256 _num) public payable {
        (bool success, ) = _logic.delegatecall(
            abi.encodeWithSignature("setVars(uint256)", _num)
        );
        require(success, "Delegatecall failed");
    }
}"},{"order":12,"type":"bullet_point","text":"Storage layout of the proxy contract and the logic contract must match when using delegatecall."},{"order":13,"type":"bullet_point","text":"Widely used in upgradable contract patterns."},{"order":14,"type":"subheading","text":"3. The staticcall Function"},{"order":15,"type":"paragraph","text":"staticcall is a low-level function identical to call, but it reverts if the called function attempts to modify the state. It corresponds to the EIP-214 'STATICCALL' opcode and is used to enforce view or pure behaviors at runtime."},{"order":16,"type":"code","text":"contract Reader {
    uint256 public value = 100;

    function getValue() public view returns (uint256) {
        return value;
    }
}

contract Caller {
    function readValue(address _addr) public view returns (bool, uint256) {
        (bool success, bytes memory data) = _addr.staticcall(
            abi.encodeWithSignature("getValue()")
        );

        if (!success) {
            return (false, 0);
        }

        uint256 result = abi.decode(data, (uint256));
        return (true, result);
    }
}"},{"order":17,"type":"subheading","text":"Security Considerations"},{"order":18,"type":"bullet_point","text":"Always check the boolean success return value of low-level calls to handle failures gracefully."},{"order":19,"type":"bullet_point","text":"Beware of reentrancy attacks when forwarding Ether and control flow via call."},{"order":20,"type":"bullet_point","text":"Ensure strict storage layout collision avoidance when utilizing delegatecall for upgradeability."}]
